CREATE COLUMN TABLE "TEST_AP"."OBNI" ("IndexType" INTEGER CS_INT NOT NULL , "Code" INTEGER CS_INT NOT NULL , "Descr" NVARCHAR(254), "UserSign" SMALLINT CS_INT, "ID" INTEGER CS_INT NOT NULL , PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBNI_IND_CODE_K" ON "TEST_AP"."OBNI" ( "IndexType" ASC, "Code" ASC )